#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<bool> checkArithmeticSubarrays(vector<int>& nums, vector<int>& l, vector<int>& r) {
        vector<bool> ans;
        for (size_t i = 0; i < l.size(); ++i) {
            vector<int> sub(nums.begin() + l[i], nums.begin() + r[i] + 1);
            sort(sub.begin(), sub.end());
            int diff = sub[1] - sub[0];
            bool ok = true;
            for (size_t j = 2; j < sub.size(); ++j) {
                if (sub[j] - sub[j - 1] != diff) {
                    ok = false;
                    break;
                }
            }
            ans.push_back(ok);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> ans = new ArrayList<>();
        for (int i = 0; i < l.length; ++i) {
            int len = r[i] - l[i] + 1;
            int[] sub = new int[len];
            System.arraycopy(nums, l[i], sub, 0, len);
            Arrays.sort(sub);
            int diff = sub[1] - sub[0];
            boolean ok = true;
            for (int j = 2; j < len; ++j) {
                if (sub[j] - sub[j - 1] != diff) {
                    ok = false;
                    break;
                }
            }
            ans.add(ok);
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number[]} l
 * @param {number[]} r
 * @return {boolean[]}
 */
var checkArithmeticSubarrays = function(nums, l, r) {
    const ans = [];
    for (let i = 0; i < l.length; ++i) {
        const sub = nums.slice(l[i], r[i] + 1).sort((a, b) => a - b);
        const diff = sub[1] - sub[0];
        let ok = true;
        for (let j = 2; j < sub.length; ++j) {
            if (sub[j] - sub[j - 1] !== diff) {
                ok = false;
                break;
            }
        }
        ans.push(ok);
    }
    return ans;
};
